"""Frontend unifié du dashboard SentriX.

Cette vue remplace la pile visuelle historique V60 -> V64 par une seule source HTML/CSS/JS.
Les APIs et contrôles serveur existants restent la source de vérité : OAuth Discord, CSRF,
permissions administrateur, diagnostics, Tickets V62, embeds et réglages du serveur.
"""
from __future__ import annotations

import logging

logger = logging.getLogger("bot.dashboard-unified-v2")

